package control

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"github.com/nicccce/meshstrata/internal/domain"
	"io"
)

const SubprotocolV2 = "meshstrata.control.v2"

// Failure reports are sent only when both endpoints negotiate this extension.
// Base V2 peers retain their original strict wire format.
const SubprotocolV2ObservationStatus = "meshstrata.control.v2.observation-status"

// SessionV2 is a separate envelope. Legacy messages never acquire new fields.
// SessionID is generated by the Controller after mTLS authentication.
type SessionV2 struct {
	Message
	SessionID          domain.ID             `json:"session_id"`
	RecoveryFormat     int                   `json:"recovery_format,omitempty"`
	ObservationRequest *ObservationRequestV2 `json:"observation_request,omitempty"`
	ObservationReport  *ObservationReportV2  `json:"observation_report,omitempty"`
}

func (m SessionV2) Validate(node domain.ID) error {
	if !m.SessionID.Valid() || m.Version != 2 {
		return fmt.Errorf("invalid v2 session")
	}
	if m.Type == "observe" || m.Type == "observation" {
		if m.Command != nil || m.Result != nil || m.Receipt != nil || m.Hello != nil || m.RecoveryFormat != 0 || m.NodeID != node || !node.Valid() || !m.MessageID.Valid() || m.SentAt.IsZero() {
			return fmt.Errorf("invalid observation envelope")
		}
		if m.Type == "observe" && m.ObservationReport == nil && m.ObservationRequest != nil && m.ObservationRequest.Valid() {
			return nil
		}
		if m.Type == "observation" && m.ObservationRequest == nil && m.ObservationReport != nil && m.ObservationReport.Valid(node) {
			return nil
		}
		return fmt.Errorf("invalid observation")
	}
	if m.ObservationRequest != nil || m.ObservationReport != nil {
		return fmt.Errorf("unexpected observation")
	}
	if m.Type == "welcome" {
		if m.Command != nil || m.Result != nil || m.Receipt != nil || m.Hello != nil || m.RecoveryFormat != 0 || m.NodeID != node || !node.Valid() || !m.MessageID.Valid() || m.SentAt.IsZero() {
			return fmt.Errorf("invalid welcome")
		}
		return nil
	}
	if m.Type == "hello" {
		if m.RecoveryFormat != 2 || m.Hello == nil || !m.Hello.Runtime {
			return fmt.Errorf("v2 recovery required")
		}
	} else if m.RecoveryFormat != 0 {
		return fmt.Errorf("unexpected recovery capability")
	}
	legacy := m.Message
	legacy.Version = Version
	return legacy.Validate(node)
}

func DecodeSessionV2(data []byte, node domain.ID) (SessionV2, error) {
	var m SessionV2
	if len(data) > MaxMessageBytes {
		return m, fmt.Errorf("control message too large")
	}
	d := json.NewDecoder(bytes.NewReader(data))
	d.DisallowUnknownFields()
	if d.Decode(&m) != nil || d.Decode(new(any)) != io.EOF {
		return m, fmt.Errorf("invalid v2 message")
	}
	// Reject duplicate keys at every level, including embedded legacy payloads.
	if !uniqueJSON(data) {
		return m, fmt.Errorf("duplicate control field")
	}
	return m, m.Validate(node)
}
func uniqueJSON(b []byte) bool {
	d := json.NewDecoder(bytes.NewReader(b))
	var value func() bool
	value = func() bool {
		t, e := d.Token()
		if e != nil {
			return false
		}
		delim, ok := t.(json.Delim)
		if !ok {
			return true
		}
		switch delim {
		case '{':
			seen := map[string]bool{}
			for d.More() {
				k, e := d.Token()
				s, ok := k.(string)
				if e != nil || !ok || seen[s] {
					return false
				}
				seen[s] = true
				if !value() {
					return false
				}
			}
		case '[':
			for d.More() {
				if !value() {
					return false
				}
			}
		default:
			return false
		}
		_, e = d.Token()
		return e == nil
	}
	return value()
}

type sessionContextKey struct{}

func WithSession(ctx context.Context, id domain.ID) context.Context {
	return context.WithValue(ctx, sessionContextKey{}, id)
}
func SessionFromContext(ctx context.Context) domain.ID {
	id, _ := ctx.Value(sessionContextKey{}).(domain.ID)
	return id
}

// UniqueJSON rejects duplicate keys recursively before strict boundary decoding.
func UniqueJSON(b []byte) bool { return uniqueJSON(b) }
